py -V:3.12 -I - <<'PY'
import json
from pathlib import Path
for f, ids in [('scratch/t14/out/census.json',{0,2,27,26,38}),('scratch/t01/inbox/t01f/output.json',None),('scratch/t01/inbox/t01l/output.json',None),('scratch/t05/people/attrs.json',None)]:
 d=json.loads(Path(f).read_text(encoding='utf-8'))
 print('\n###',f)
 if f.endswith('census.json'):
  for r in d['tables']:
   if r['table_type'] in ids: print(json.dumps(r,ensure_ascii=False)[:2500])
 elif f.endswith('t01f/output.json'):
  print('acceptance',d.get('acceptance')); print('checks',d.get('checks',{}).keys()); print('named anchors',d.get('checks',{}).get('continent_and_nation_named_anchors')); print('parents',d.get('checks',{}).get('cpcm_named_anchors'))
 elif f.endswith('t01l/output.json'):
  print('acceptance',d.get('acceptance')); print('rowcodec',d.get('row_codec'))
 else:
  print({k:d.get(k) for k in ('status','count','class_counts','class_payload_budget')})
PY

